await api.post('/orders', body, {
  headers: { 'X-Requested-With': 'XMLHttpRequest' },
  withCredentials: true,
})
// Cookie flags (Set-Cookie from the API):
// HttpOnly; Secure; SameSite=Lax; Path=/
// Mutations are POST. GET /logout is still CSRF under Lax.
// Bearer from memory: omit withCredentials; CSRF usually N/A.

